This FIFO uses all 17 slots and rejects overflow without modifying its state. The invariant is 0 ≤ size ≤ 17 and tail = (head + size) modulo 17; size distinguishes empty from full even when head equals tail. Compile with g++ -std=c++17 fifo.cpp -o fifo and run ./fifo; the code keeps test assertions enabled.

```cpp
#ifdef NDEBUG
#undef NDEBUG
#endif
#include <array>
#include <cassert>
#include <cstddef>
#include <iostream>

class BoundedFIFO {
public:
    static constexpr std::size_t capacity = 17;

    bool push(int value) {
        if (size_ == capacity) return false;
        data_[tail_] = value;
        tail_ = (tail_ + 1) % capacity;
        ++size_;
        return true;
    }

    bool pop(int& value) {
        if (size_ == 0) return false;
        value = data_[head_];
        head_ = (head_ + 1) % capacity;
        --size_;
        return true;
    }

    std::size_t size() const { return size_; }
    bool empty() const { return size_ == 0; }
    bool full() const { return size_ == capacity; }

private:
    std::array<int, capacity> data_{};
    std::size_t head_ = 0;
    std::size_t tail_ = 0;
    std::size_t size_ = 0;
};

int main() {
    BoundedFIFO fifo;
    int value = -1;

    // Empty pop fails and preserves the output argument.
    assert(!fifo.pop(value));
    assert(value == -1);
    assert(fifo.empty());

    // All 17 slots are usable.
    for (int i = 0; i < 17; ++i) {
        assert(fifo.push(i));
        assert(fifo.size() == static_cast<std::size_t>(i + 1));
    }
    assert(fifo.full());

    // Overflow rejection preserves size and every queued value.
    assert(!fifo.push(999));
    assert(fifo.size() == 17);
    for (int i = 0; i < 17; ++i) {
        assert(fifo.pop(value));
        assert(value == i);
    }
    assert(fifo.empty());
    assert(!fifo.pop(value));

    // Move head forward, then wrap tail while unread values remain.
    for (int i = 0; i < 17; ++i) assert(fifo.push(i));
    for (int i = 0; i < 10; ++i) {
        assert(fifo.pop(value));
        assert(value == i);
    }
    for (int i = 17; i < 27; ++i) assert(fifo.push(i));
    assert(fifo.full());
    assert(!fifo.push(999));

    // Draining also wraps head and preserves FIFO order.
    for (int i = 10; i < 27; ++i) {
        assert(fifo.pop(value));
        assert(value == i);
    }
    assert(fifo.empty());
    assert(!fifo.pop(value));

    // The queue remains reusable after wraparound.
    assert(fifo.push(42));
    assert(fifo.pop(value));
    assert(value == 42);
    assert(fifo.empty());

    std::cout << "All tests passed\n";
}
```

The lower median is 4. Copying the input before calling std::nth_element preserves the caller’s array; empty input throws std::invalid_argument.

The correct zero-based index is (n − 1) / 2 using integer division. For odd n = 2m + 1, this gives m, the single middle position; for even n = 2m, it gives m − 1, the lower of the two middle positions. std::nth_element puts the value that would occupy that index in sorted order there, including when values repeat.

Compile with g++ -std=c++17 median.cpp -o median and run ./median. Assertions remain enabled in this test program.

```cpp
#ifdef NDEBUG
#undef NDEBUG
#endif
#include <algorithm>
#include <cassert>
#include <cstddef>
#include <iostream>
#include <stdexcept>
#include <vector>

int lower_median(const std::vector<int>& input) {
    if (input.empty()) {
        throw std::invalid_argument("lower_median requires nonempty input");
    }

    std::vector<int> copy = input;
    const std::size_t index = (copy.size() - 1) / 2;
    auto middle = copy.begin() +
                  static_cast<std::vector<int>::difference_type>(index);
    std::nth_element(copy.begin(), middle, copy.end());
    return *middle;
}

int main() {
    const auto check = [](const std::vector<int>& input, int expected) {
        const std::vector<int> original = input;
        assert(lower_median(input) == expected);
        assert(input == original);
    };

    check({9, 1, 4, 4, 7, 2}, 4); // Requested array and duplicates.
    check({5, 5, 5, 5}, 5);       // All values equal.
    check({9, 1, 7, 3, 5}, 5);    // Odd size: sorted index 2.
    check({8, 2, 6, 4}, 4);       // Even size: lower middle, index 1.
    check({42}, 42);              // Singleton: index 0.

    const std::vector<int> empty;
    bool rejected = false;
    try {
        (void)lower_median(empty);
    } catch (const std::invalid_argument&) {
        rejected = true;
    }
    assert(rejected);
    assert(empty.empty());

    std::cout << "All tests passed\n";
}
```

No—retrying with a stale desired can lose an increment. Starting at 0, two threads both set expected=0 and desired=1. Thread A successfully changes 0→1; thread B’s attempt fails and updates its expected to 1, but leaves desired=1. B then successfully changes 1→1: two increments have completed, yet the count is only 1.

Recompute desired on every attempt. A spurious failure may leave expected unchanged; the loop still retries safely, and only a successful comparison completes the increment. Relaxed ordering suffices for this counter; joining all threads before checking ensures their work has finished.

Compile with g++ -std=c++17 -O2 -pthread counter.cpp -o counter and run ./counter. This test stays below the unsigned counter’s wraparound limit.

```cpp
#ifdef NDEBUG
#undef NDEBUG
#endif
#include <atomic>
#include <cassert>
#include <cstdint>
#include <iostream>
#include <thread>
#include <vector>

void increment(std::atomic<std::uint64_t>& counter) {
    std::uint64_t expected = counter.load(std::memory_order_relaxed);
    for (;;) {
        const std::uint64_t desired = expected + 1;
        if (counter.compare_exchange_weak(
                expected, desired,
                std::memory_order_relaxed,
                std::memory_order_relaxed)) {
            return;
        }
        // Failure refreshes expected, including on spurious failure.
        // Recompute desired from that expected on the next iteration.
    }
}

int main() {
    constexpr unsigned thread_count = 8;
    constexpr std::uint64_t increments_per_thread = 100000;
    constexpr std::uint64_t expected_count =
        thread_count * increments_per_thread;

    std::atomic<std::uint64_t> counter{0};
    std::vector<std::thread> threads;
    threads.reserve(thread_count);

    for (unsigned i = 0; i < thread_count; ++i) {
        threads.emplace_back([&counter] {
            for (std::uint64_t j = 0; j < increments_per_thread; ++j) {
                increment(counter);
            }
        });
    }
    for (auto& thread : threads) {
        thread.join();
    }

    const auto actual = counter.load(std::memory_order_relaxed);
    assert(actual == expected_count);
    std::cout << "All tests passed; final count = " << actual << '\n';
}
